jsonTools.init:
function init(eli) {
  // ELI Agent: Draft Document (tools/eli_agent parts 30, 60 and 66) in a bundle of its own
  // (docs/ELI_AGENT_SPLIT_PLAN.md step 3). ELI Agent, the host, hands over what it uses (H): the run, its screens and
  // areas, and the shared helpers below, by name. Beside an ELI Agent that doesn't hand over every one of them (one
  // that still holds Draft Document itself: an older one, or one reverted to it) this bundle does nothing.
  var H = typeof eli.dispatch === "function" ? eli.dispatch("eli_agent", "host") : null;
  // A newer ELI Agent started in this session (an update installed while ELI was open): this bundle starts again
  // beside it, and this copy stops listening. Listened for even while it does nothing, so a host that arrives later
  // gets it too.
  var reattach = eli.bus && typeof eli.bus.on === "function" ? eli.bus.on("eli_agent:host", function (e) {
    if (!e || !e.host || e.host === H) return;
    if (typeof reattach === "function") reattach();
    init(eli);
  }) : null;
  if (!H || !(H.apiVersion >= 1) || !H.fn) return;
  var _aiJsonCall = H.fn._aiJsonCall, _aiTextCall = H.fn._aiTextCall, _bodyHeader = H.fn._bodyHeader,
    _clAllCards = H.fn._clAllCards, _closeAgentOverlay = H.fn._closeAgentOverlay, _dtAll = H.fn._dtAll,
    _dtExcluded = H.fn._dtExcluded, _dtFor = H.fn._dtFor, _dtIntakeDetails = H.fn._dtIntakeDetails,
    _dtName = H.fn._dtName, _dtRuns = H.fn._dtRuns, _egArea = H.fn._egArea, _egRun = H.fn._egRun,
    _egScreen = H.fn._egScreen, _esc = H.fn._esc, _getAgentSettings = H.fn._getAgentSettings, _ivText = H.fn._ivText,
    _loadGuidance = H.fn._loadGuidance, _loadPlaybookSnippets = H.fn._loadPlaybookSnippets,
    _renderOverlayBody = H.fn._renderOverlayBody, _retReport = H.fn._retReport, _retResolveAll = H.fn._retResolveAll,
    _scrollSoon = H.fn._scrollSoon, _stageStrip = H.fn._stageStrip, _stream = H.fn._stream, _toast = H.fn._toast,
    _typeMatches = H.fn._typeMatches, _wireCancelOnly = H.fn._wireCancelOnly,
    _egInPlace = H.fn._egInPlace, _egMarkedHtml = H.fn._egMarkedHtml,   // [DRAFT-CARD]
    _egWriteLineHtml = H.fn._egWriteLineHtml;   // [DRAFT-WRITE]
  if ([_aiJsonCall, _aiTextCall, _bodyHeader, _clAllCards, _closeAgentOverlay, _dtAll, _dtExcluded, _dtFor,
    _dtIntakeDetails, _dtName, _dtRuns, _egArea, _egRun, _egScreen, _esc, _getAgentSettings, _ivText, _loadGuidance,
    _loadPlaybookSnippets, _renderOverlayBody, _retReport, _retResolveAll, _scrollSoon, _stageStrip, _stream, _toast,
    _typeMatches, _wireCancelOnly, _egInPlace, _egMarkedHtml, _egWriteLineHtml].indexOf(undefined) >= 0) return;

  // ─── Draft Document: interview pane ─────────────────────────────
  // Conversational Q&A. Each turn = an agent question + the user's
  // answer. After 3-5 turns the agent decides intake is sufficient
  // and offers a "Generate Draft" button.
  function _bodyInterview() {
    var iv = _egRun().interview || {};
    var turns = iv.turns || [];
    var seed = iv.seed || "";
    var turnsHtml = (seed ? '<div class="_eg_iv_turn _eg_iv_user"><div class="_eg_iv_role">YOU</div><div class="_eg_iv_text">' + _esc(seed) + '</div></div>' : "") +
      turns.map(function (t) {
        var qHtml = '<div class="_eg_iv_turn _eg_iv_agent"><div class="_eg_iv_role">📝 AGENT</div><div class="_eg_iv_text">' + _esc(t.question || "") + '</div></div>';
        var aHtml = '';
        if (t.answer) {
          aHtml = '<div class="_eg_iv_turn _eg_iv_user"><div class="_eg_iv_role">YOU</div><div class="_eg_iv_text">' + _esc(t.answer) + '</div></div>';
        }
        return qHtml + aHtml;
      }).join("");
    // The pending agent question (waiting for user answer).
    var pending = iv.nextQuestions && iv.nextQuestions.length ? iv.nextQuestions[0] : null;
    var inputArea = "";
    if (pending) {
      var qHtml = '<div class="_eg_iv_turn _eg_iv_agent"><div class="_eg_iv_role">📝 AGENT</div><div class="_eg_iv_text">' + _esc(pending.question || "") + '</div></div>';
      // Render input based on question type.
      if (pending.type === "choice" && Array.isArray(pending.options) && pending.options.length) {
        inputArea = qHtml +
          '<div class="_eg_iv_choices">' +
            pending.options.map(function (o) {
              return '<button type="button" class="_eg_btn_secondary _eg_iv_choice_btn" data-eg-iv-choice="' + _esc(o) + '">' + _esc(o) + '</button>';
            }).join("") +
          '</div>' +
          '<div class="_eg_iv_input_row">' +
            '<input id="_eg_iv_text_input" type="text" class="_eg_iv_text_input" placeholder="…or type a custom answer" />' +
            '<button id="_eg_iv_submit" type="button" class="_eg_btn_primary">Send</button>' +
          '</div>';
      } else {
        inputArea = qHtml +
          '<div class="_eg_iv_input_row">' +
            '<input id="_eg_iv_text_input" type="text" class="_eg_iv_text_input" placeholder="Type your answer…" autofocus />' +
            '<button id="_eg_iv_submit" type="button" class="_eg_btn_primary">Send</button>' +
          '</div>';
      }
    } else if (iv.thinking) {
      // The gap this fills: between sending an answer and the next question
      // arriving there is an AI call, and every branch below used to be
      // false — so the pane went blank and the thread appeared to stop.
      inputArea =
        '<div class="_eg_iv_turn _eg_iv_agent _eg_iv_thinking">' +
          '<div class="_eg_iv_role">📝 AGENT</div>' +
          '<div class="_eg_iv_text">' +
            (turns.length ? "Reading your answer" : "Preparing the first question") +
            '<i class="_eg_st_ell"><b></b><b></b><b></b></i>' +
          '</div>' +
        '</div>';
    } else if (iv.intakeComplete) {
      // Ready to draft. Said in the thread, not only on the button: the
      // turn that ENDS the interview should read like the ones before it,
      // or the questions just stop and a button appears.
      inputArea =
        '<div class="_eg_iv_turn _eg_iv_agent">' +
          '<div class="_eg_iv_role">📝 AGENT</div>' +
          '<div class="_eg_iv_text">That is enough to start' +
            (iv.agreementType ? " the " + _esc(iv.agreementType) : " drafting") +
            '. I will settle the full structure first, check it for anything ' +
            'missing, then draft each part — you see the outline before a ' +
            'word is written.</div>' +
        '</div>' +
        '<div class="_eg_actions_row _eg_actions_sticky">' +
          '<button id="_eg_iv_more" type="button" class="_eg_btn_secondary">Add more context</button>' +
          '<button id="_eg_iv_draft" type="button" class="_eg_btn_primary _eg_btn_apply">Generate Draft →</button>' +
        '</div>';
    }
    // The tail is what the reader must be looking at after every turn: the
    // newest question and the box to answer it, or the thinking row.
    return _bodyHeader() +
      _stageStrip() +
      '<div class="_eg_iv_thread">' + turnsHtml + '</div>' +
      '<div id="_eg_iv_tail">' + inputArea + '</div>';
  }
  function _wireInterviewControls(body) {
    // First time: kick off the interview if no questions yet. `thinking`
    // is part of the guard because _runInterviewTurn now repaints to show
    // the waiting row, and this wiring runs again on that repaint.
    var iv = _egRun().interview;
    if (!iv.turns.length && !iv.nextQuestions && !iv.intakeComplete && !iv.thinking) {
      _runInterviewTurn("");  // initial — no answer to process
      return;
    }
    // Choice buttons.
    body.querySelectorAll("[data-eg-iv-choice]").forEach(function (btn) {
      btn.onclick = function () {
        var answer = btn.getAttribute("data-eg-iv-choice");
        _submitInterviewAnswer(answer);
      };
    });
    // Free-text input + Send.
    var textInput = body.querySelector("#_eg_iv_text_input");
    var sendBtn = body.querySelector("#_eg_iv_submit");
    if (sendBtn) sendBtn.onclick = function () {
      var v = textInput ? (textInput.value || "").trim() : "";
      if (!v) return;
      _submitInterviewAnswer(v);
    };
    if (textInput) {
      textInput.onkeydown = function (e) {
        if (e.key === "Enter") { e.preventDefault(); if (sendBtn) sendBtn.click(); }
      };
      try { textInput.focus(); } catch (_) {}
    }
    // Post-intake actions.
    var draftBtn = body.querySelector("#_eg_iv_draft");
    if (draftBtn) draftBtn.onclick = function () { _runDraftPipeline(); };
    var moreBtn = body.querySelector("#_eg_iv_more");
    if (moreBtn) moreBtn.onclick = function () {
      _egRun().interview.intakeComplete = false;
      _runInterviewTurn(null);  // ask another question
    };
    // Follow the thread. The screen-level scroll only fires on ENTERING a
    // screen, and the interview stays on one screen for every turn — so
    // each new question arrived below the fold and the pane looked stuck.
    //
    // "end" on the last turn, "nearest" on every other. Generate Draft is
    // the one thing here the reader has to find, and "nearest" leaves it
    // wherever it already was — which is how you finish answering and see
    // nothing happen. Its scroll-margin-bottom keeps it clear of the
    // chat's input bar.
    _scrollSoon(body.querySelector("#_eg_iv_tail"),
      iv.intakeComplete ? "end" : "nearest");
  }
  function _submitInterviewAnswer(answer) {
    var iv = _egRun().interview;
    var pending = iv.nextQuestions && iv.nextQuestions[0];
    if (!pending) return;
    iv.turns.push({ question: pending.question, answer: String(answer), type: pending.type || "text" });
    iv.nextQuestions = iv.nextQuestions.slice(1);
    // One repaint, not two: _runInterviewTurn paints the waiting row
    // itself, and painting before it showed the answer with nothing under
    // it for a frame.
    if (iv.nextQuestions.length) _renderOverlayBody();
    else _runInterviewTurn(answer);  // get next question(s) from agent
  }
  // Ask the AI for the next intake question (or signal intake is done).
  function _runInterviewTurn(lastAnswer) {
    if (!_egRun()) return;
    var prompt = _buildInterviewTurnPrompt(_egRun(), lastAnswer);
    _egRun().interview.thinking = true;
    _renderOverlayBody();
    _aiJsonCall(prompt, { intakeComplete: "boolean", questions: "object", agreementType: "string" })
      .then(function (result) {
        if (!_egRun()) return;
        _egRun().interview.thinking = false;
        if (result && result.intakeComplete) {
          _egRun().interview.intakeComplete = true;
          _egRun().interview.nextQuestions = null;
          if (result.agreementType) _egRun().interview.agreementType = result.agreementType;
        } else if (result && Array.isArray(result.questions) && result.questions.length) {
          _egRun().interview.nextQuestions = result.questions;
          if (result.agreementType && !_egRun().interview.agreementType) {
            _egRun().interview.agreementType = result.agreementType;
          }
        } else {
          // Empty result — treat as intake complete to avoid getting stuck.
          _egRun().interview.intakeComplete = true;
        }
        _renderOverlayBody();
      })
      .catch(function (err) {
        if (_egRun()) _egRun().interview.thinking = false;
        _egRun().status = "error";
        _egRun().error = (err && err.message) || String(err);
        _renderOverlayBody();
      });
  }

  // ─── Draft Document: outline review ─────────────────────────────
  // A one-word badge saying where this section's language comes from. The
  // whole point of retrieval is that a reader can see, before drafting
  // starts, how much of the document is our own reviewed language and how
  // much the model is about to invent.
  var RET_LABEL = {
    locked: { text: "Playbook (locked)", cls: "_eg_src_locked" },
    playbook: { text: "Playbook", cls: "_eg_src_playbook" },
    template: { text: "Our template", cls: "_eg_src_template" },
    adapt: { text: "Adapted", cls: "_eg_src_adapt" },
    generate: { text: "Newly drafted", cls: "_eg_src_generate" },
  };
  function _retBadge(tier, provenance) {
    var L = RET_LABEL[tier] || RET_LABEL.generate;
    return '<span class="_eg_src_badge ' + L.cls + '"' +
      (provenance ? ' title="' + _esc(provenance) + '"' : '') + '>' + L.text + '</span>';
  }
  function _retSummaryHtml() {
    var rep = _egRun() && _egRun().retrievalReport;
    if (!rep || !rep.total) return "";
    var gap = rep.gaps && rep.gaps.length
      ? '<div class="_eg_src_gaps"><b>Nothing on file for:</b> ' +
        _esc(rep.gaps.slice(0, 8).join(", ")) +
        (rep.gaps.length > 8 ? " +" + (rep.gaps.length - 8) + " more" : "") +
        ' — these will be drafted from standard practice, and are the ' +
        'clauses worth adding to the playbook.</div>'
      : "";
    return '<div class="_eg_src_summary">' +
      '<div class="_eg_src_headline">' + rep.reused + ' of ' + rep.total +
        ' sections come from ELI\'s own language (' + rep.reusePct + '%)</div>' +
      '<div class="_eg_src_tiers">' +
        Object.keys(RET_LABEL).filter(function (k) { return rep.byTier[k]; })
          .map(function (k) { return _retBadge(k) + '<b>' + rep.byTier[k] + '</b>'; })
          .join("") +
      '</div>' + gap +
    '</div>';
  }
  function _bodyStructure() {
    var iv = _egRun().interview || {};
    return _bodyHeader() +
      _stageStrip() +
      '<div class="_eg_section_label">BUILDING THE STRUCTURE</div>' +
      '<div class="_eg_status_box">' +
        '<div class="_eg_status_dot"></div>' +
        '<div>Setting out every part a ' + _esc(iv.agreementType || "document") +
          ' needs — following how our own documents of this kind are built.</div>' +
      '</div>';
  }
  // Completeness, checked repeatedly, before a word is drafted. A missing
  // clause costs one line here and a renegotiation later.
  function _bodyStructureAudit() {
    var rounds = _egRun().structureRounds || [];
    var added = _egRun().structureAdded || [];
    return _bodyHeader() +
      _stageStrip() +
      '<div class="_eg_section_label">CHECKING FOR ANYTHING MISSING</div>' +
      '<div class="_eg_status_box">' +
        '<div class="_eg_status_dot"></div>' +
        '<div>Round ' + (_egRun().structureRound || 1) + ' of at most ' +
          STRUCTURE_AUDIT_MAX + ' — ' + (_egRun().outline || []).length +
          ' clauses so far.</div>' +
      '</div>' +
      rounds.map(function (r) {
        return '<div class="_eg_audit_round">' +
          '<span class="_eg_audit_mark">' + (r.complete ? "✓" : "+") + '</span>' +
          '<div class="_eg_audit_text">Round ' + r.round + ' — ' +
            (r.complete ? "nothing missing" :
              "added " + r.found + " clause" + (r.found === 1 ? "" : "s")) + '</div>' +
        '</div>';
      }).join("") +
      (added.length
        ? '<div class="_eg_fu_item"><b>Added by the check:</b> ' + _esc(added.join(", ")) + '</div>'
        : "");
  }
  function _bodyOutline() {
    var sections = (_egRun().outline || []);
    var ret = _egRun().retrieval || {};
    var rows = sections.map(function (s) {
      var r = ret[s.id];
      return '<div class="_eg_outline_row">' +
        '<span class="_eg_outline_num">§' + _esc(String(s.num || "?")) + '</span>' +
        '<div>' +
          '<div class="_eg_outline_name">' + _esc(s.name || "") +
            (r ? _retBadge(r.tier, r.provenance) : '') +
            // Worth showing: these are the clauses the first pass forgot.
            (s._addedByAudit
              ? '<span class="_eg_src_badge _eg_src_added" title="' +
                _esc(s.focus || "") + '">Added by the check</span>' : '') + '</div>' +
          '<div class="_eg_outline_focus">' + _esc(s.focus || "") + '</div>' +
          (r && r.provenance
            ? '<div class="_eg_outline_src">' + _esc(r.provenance) + '</div>' : '') +
        '</div>' +
      '</div>';
    }).join("");
    var held = _aaHeld();
    return _bodyHeader() +
      _stageStrip() +
      '<div class="_eg_section_label" id="_eg_gate">PROPOSED OUTLINE (' + sections.length + ' sections)</div>' +
      '<div class="_eg_compose_hint">' + (held
        ? 'Review what I plan to draft, then continue.'
        : 'This is what I plan to draft. It starts by itself — stop me if it is wrong.') +
      '</div>' +
      _retSummaryHtml() +
      rows +
      '<div class="_eg_actions_row _eg_actions_sticky">' +
        (held ? '<button id="_eg_outline_back" type="button" class="_eg_btn_secondary">← Back</button>' : "") +
        _aaRow("Drafting starts", "Draft Sections") +
      '</div>';
  }
  function _wireOutlineControls(body) {
    var backBtn = body.querySelector("#_eg_outline_back");
    if (backBtn) backBtn.onclick = function () {
      _aaStop();
      _egRun().status = "interview";
      _renderOverlayBody();
    };
    _wireAutoAdvance(body, _runSectionDrafting);
  }

  // ─── [AUTO-ADVANCE] ───────────────────────────────────────────────
  // A screen the run passes THROUGH rather than stops at. The outline is
  // the only one: it is worth SEEING — the first look at what the document
  // will contain — but it is not a decision, because nothing is drafted
  // yet and every section is read again afterwards. Stopping dead on it
  // made the run look stuck.
  //
  // Deliberately NOT used on the drafted sections. That screen is the only
  // place the prose can be read clause by clause and sections dropped, so
  // a timer there takes away the review it exists for. Its primary says
  // "Check it over", not "Insert" — that mislabelling is what made you
  // click Insert twice, and it is fixed by the label, not by skipping the
  // screen.
  // TO REMOVE: delete to [/AUTO-ADVANCE] + _aaRow/_wireAutoAdvance/_aaStart
  // at their call sites in the outline screen and the draft pipeline.
  var AA_SECONDS = 6;
  // Held is one flag for the whole run, not one per screen: a reader who
  // says "wait" once is saying they want to drive, and asking again two
  // screens later is not listening.
  function _aaHeld() { return !!(_egRun() && _egRun()._aaHeld); }
  function _aaStop() {
    if (!_egRun() || !_egRun()._aaTimer) return;
    clearInterval(_egRun()._aaTimer);
    _egRun()._aaTimer = null;
  }
  // A whole repaint per second would fight the reader scrolling down a
  // thirty-clause outline, so only the digit is written.
  function _aaStart(go) {
    if (!_egRun()) return;
    _aaStop();
    if (_aaHeld()) return;
    var stage = _egRun().status;
    _egRun()._aaLeft = AA_SECONDS;
    _egRun()._aaTimer = setInterval(function () {
      // Cancelled, gone back, held, or the panel was closed.
      if (!_egRun() || _egRun().status !== stage || _aaHeld()) { _aaStop(); return; }
      _egRun()._aaLeft--;
      var el = document.getElementById("_eg_aa_left");
      if (el) el.textContent = String(Math.max(0, _egRun()._aaLeft));
      if (_egRun()._aaLeft > 0) return;
      _aaStop();
      go();
    }, 1000);
  }
  // `what` is what is about to happen ("Drafting starts"); `now` is the
  // button for skipping the wait ("Draft Sections").
  function _aaRow(what, now) {
    if (_aaHeld()) {
      return '<button id="_eg_aa_go" type="button" class="_eg_btn_primary _eg_btn_apply">' +
        _esc(now) + ' →</button>';
    }
    return '<span class="_eg_aa_count">' + _esc(what) + ' in ' +
        '<b id="_eg_aa_left">' + (_egRun()._aaLeft || 0) + '</b>s</span>' +
      '<button id="_eg_aa_hold" type="button" class="_eg_btn_secondary">Wait — let me read it</button>' +
      '<button id="_eg_aa_go" type="button" class="_eg_btn_primary _eg_btn_apply">' +
        _esc(now) + ' now →</button>';
  }
  function _wireAutoAdvance(body, go) {
    var goBtn = body.querySelector("#_eg_aa_go");
    if (goBtn) goBtn.onclick = function () { _aaStop(); go(); };
    var hold = body.querySelector("#_eg_aa_hold");
    if (hold) hold.onclick = function () {
      _aaStop();
      _egRun()._aaHeld = true;
      _renderOverlayBody();
    };
  }
  // ─── [/AUTO-ADVANCE] ──────────────────────────────────────────────

  // ─── Draft Document: drafting progress + review ─────────────────
  // What each state says for itself. The old screen marked EVERY section
  // "drafting" before the first call went out, so thirty rows sat on ⚙
  // "drafting…" for the whole run and nothing appeared to move — only three
  // are ever actually in flight.
  var DRAFT_ROW = {
    done:     { icon: "✓", word: "drafted" },
    failed:   { icon: "⚠", word: "failed" },
    drafting: { icon: "⚙", word: "drafting" },
    queued:   { icon: "○", word: "queued" },
  };
  function _bodyDrafting() {
    var sections = _egRun().outline || [];
    var done = 0, firstLive = "";
    var rows = sections.map(function (s) {
      var st = s.status || "queued";
      var r = DRAFT_ROW[st] || DRAFT_ROW.queued;
      if (st === "done") done++;
      // The anchor is the first row still working, so the list follows the
      // work down rather than sitting at the top of a long outline.
      var id = "";
      if (!firstLive && st === "drafting") { firstLive = "_eg_dr_live"; id = ' id="_eg_dr_live"'; }
      return '<div class="_eg_bucket_row _eg_bucket_' + st + '"' + id + '>' +
        '<span class="_eg_bucket_icon">' + r.icon + '</span>' +
        '<div class="_eg_bucket_name">§' + _esc(String(s.num || "?")) + ' ' + _esc(s.name || "") + '</div>' +
        '<div class="_eg_bucket_focus">' + _esc(s.focus || "") + '</div>' +
        '<div class="_eg_bucket_count">' + r.word +
          (st === "drafting" ? '<i class="_eg_st_ell"><b></b><b></b><b></b></i>' : "") +
        '</div>' +
      '</div>';
    }).join("");
    var pct = sections.length ? Math.round((done / sections.length) * 100) : 0;
    return _bodyHeader() +
      _stageStrip() +
      '<div class="_eg_section_label">DRAFTING (' + done + '/' + sections.length + ')</div>' +
      '<div class="_eg_dr_bar"><span style="width:' + pct + '%"></span></div>' +
      '<div class="_eg_bucket_list">' + rows + '</div>' +
      // No second activity feed here: _bodyHeader already renders it, and a
      // duplicate would collide on #_eg_stream_rows. It follows itself while
      // the run is working, which is why this screen does not also scroll.
      '<div class="_eg_actions_row">' +
        '<button id="_eg_cancel_plan" type="button" class="_eg_btn_secondary">Cancel</button>' +
      '</div>';
  }
  // Follow the work down the list. The screen-level scroll fires only on
  // ENTERING a screen, and drafting stays on one screen for the whole run
  // — so on a thirty-clause outline everything past the fold happened
  // where the reader could not see it.
  function _wireDraftingControls(body) {
    _wireCancelOnly(body);
    _scrollSoon(body.querySelector("#_eg_dr_live"), "nearest");
  }
  // [DRAFT-CARD] A drafted part as Revise's cards show a new clause (GUI parity, the owner 10-23): ELI's words green on
  // soft green, yours gold; ✎ Edit opens it where it stands (the shared editor, [IN-PLACE]), ↺ Reset puts ELI's back.
  // Only the part's words change — inserted as they read, as before.
  function _ddPartHtml(s) {
    var eliT = s._eli != null ? s._eli : String(s.content || "");
    return _egMarkedHtml("", eliT, String(s.content || ""), "_eg_ours", "_td_ours");
  }
  function _bodyDraftReview() {
    var sections = _egRun().outline || [];
    var rows = sections.map(function (s) {
      var status = _egRun().draftAcceptance[s.id] || "accept";
      var statusCls = "_eg_draft_section_" + status;
      var edited = s._eli != null && s._eli !== String(s.content || "");
      return '<div class="_eg_draft_section ' + statusCls + '" id="_eg_draft_' + _esc(s.id) + '">' +
        '<div class="_eg_draft_section_head">' +
