      ph += _dcPlaceholders(r.text).length;
    });
    var meta = rows.length + " paragraph" + (rows.length === 1 ? "" : "s") + " · " +
      words + " words" +
      (ph ? " · " + ph + " placeholder" + (ph === 1 ? "" : "s") + " still to fill" : "");
    return '<div class="_eg_dp_meta">' + _esc(meta) + '</div>' +
      '<div class="_eg_dp_page">' + rows.map(_dpRowHtml).join("") + '</div>';
  }

  // opts: { label, onGo } — the dialog's primary does exactly what the
  // screen it was opened from does, so reading the draft never becomes a
  // second, different way to insert it.
  function _openDraftPreview(opts) {
    var o = opts || {};
    showEliDialog({
      title: (_dtName() || "Draft") + " — as it will be inserted",
      icon: "📄",
      size: "wide",
      scroll: "internal",
      body: _dpBodyHtml(),
      primary: o.onGo ? { label: o.label || "Insert", onclick: function () { o.onGo(); } } : null,
      secondary: { label: "Close" },
    });
  }
  // ─── [/DRAFT-PREVIEW] ─────────────────────────────────────────────

  // ─── [DRAFT-VERIFY-UI] ────────────────────────────────────────────
  // The screens between "sections are drafted" and "insert into the
  // document": what the checks found, and what the reader is agreeing to.
  // TO REMOVE: delete to [/DRAFT-VERIFY-UI] + the three body cases.

  var DC_KIND_LABEL = {
    failed: "Failed to draft",
    empty: "Empty section",
    dangling_ref: "Cross-reference to nothing",
    undefined_term: "Undefined term",
    unused_definition: "Unused definition",
    placeholder: "Placeholder to fill",
    party_drift: "Parties named inconsistently",
    duplicate_section: "Duplicate section",
    numbering: "Numbering",
  };

  function _bodyDraftAudit() {
    var rounds = (_egRun().auditRounds || []);
    var rows = rounds.map(function (r) {
      return '<div class="_eg_audit_round">' +
        '<span class="_eg_audit_mark">' + (r.clean ? "✓" : "●") + '</span>' +
        '<div class="_eg_audit_text">Round ' + r.round + ' — ' +
          (r.clean ? "nothing missing"
                   : r.gaps + " gap" + (r.gaps === 1 ? "" : "s") + ", " +
                     r.problems + " problem" + (r.problems === 1 ? "" : "s") +
                     (r.drafted ? " · drafted " + r.drafted : "")) +
        '</div>' +
      '</div>';
    }).join("");
    return _bodyHeader() +
      _stageStrip() +
      '<div class="_eg_section_label">CHECKING THE DRAFT</div>' +
      '<div class="_eg_status_box">' +
        '<div class="_eg_status_dot"></div>' +
        '<div>Reading it back as if the other side sent it — what is missing, ' +
          'and does it still protect us? (round ' + (_egRun().auditRound || 1) +
          ' of at most ' + DRAFT_AUDIT_MAX + ')</div>' +
      '</div>' + rows +
      '<div class="_eg_actions_row">' +
        // NOT _eg_cancel_plan: that aborts the run and throws the draft
        // away. Skipping the check keeps it and goes to the review.
        '<button id="_eg_audit_skip" type="button" class="_eg_btn_secondary">Skip the check</button>' +
      '</div>';
  }

  function _wireDraftAuditControls(body) {
    var skip = body.querySelector("#_eg_audit_skip");
    if (skip) skip.onclick = function () {
      if (!_egRun()) return;
      _egRun().auditSkipped = true;
      var kept = (_egRun().outline || []).filter(function (s) {
        return (_egRun().draftAcceptance[s.id] || "accept") === "accept";
      });
      _egRun().draftCheck = _dcCheck(kept, _dtName());
      _egRun().status = "draft_verify";
      _renderOverlayBody();
    };
  }

  function _bodyDraftGapfill() {
    var added = (_egRun().outline || []).filter(function (s) { return s._fromAudit; });
    return _bodyHeader() +
      _stageStrip() +
      '<div class="_eg_section_label">DRAFTING WHAT WAS MISSING</div>' +
      '<div class="_eg_status_box">' +
        '<div class="_eg_status_dot"></div>' +
        '<div>The check found ' + added.length + ' clause' + (added.length === 1 ? "" : "s") +
          ' missing. Adding ' + (added.length === 1 ? "it" : "them") + ' rather than just ' +
          'reporting the gap.</div>' +
      '</div>' +
      added.map(function (s) {
        return '<div class="_eg_audit_round">' +
          '<span class="_eg_audit_mark">' + (s.status === "done" ? "✓" : "○") + '</span>' +
          '<div class="_eg_audit_text">§' + _esc(String(s.num)) + ' ' + _esc(s.name) +
            _retBadge(s.source || "generate", s.provenance) + '</div>' +
        '</div>';
      }).join("");
  }

  // The last screen before anything is written. Everything the reader is
  // agreeing to, in one place: where the language came from, what the
  // deterministic check found, and what the audit could not fix.
  function _bodyDraftVerify() {
    var sections = (_egRun().outline || []).filter(function (s) {
      return (_egRun().draftAcceptance[s.id] || "accept") === "accept";
    });
    var chk = _egRun().draftCheck || { issues: [], blockers: 0, warnings: 0 };
    var findings = (_egRun().auditFindings || []);
    var problems = findings.filter(function (f) { return f.kind === "problem"; });
    var openGaps = findings.filter(function (f) {
      // A gap the agent went on to draft is not still a gap.
      return f.kind === "gap" && !(_egRun().outline || []).some(function (s) {
        return s._fromAudit && _dcNorm(s.name) === _dcNorm(f.clause);
      });
    });

    var rows = [];
    rows.push(["Sections to insert", sections.length + " section" + (sections.length === 1 ? "" : "s") +
      ", appended at the end of the open document. This is the only step " +
      "that writes anything — nothing has touched the document so far."]);
    var rep = _egRun().retrievalReport;
    if (rep && rep.total) {
      rows.push(["Where the language came from",
        rep.reused + " of " + rep.total + " sections (" + rep.reusePct + "%) are ELI's own " +
        "reviewed language. The rest were drafted for this document."]);
    }
    if (chk.blockers) {
      rows.push(["Must be fixed first", chk.blockers + " blocking issue" +
        (chk.blockers === 1 ? "" : "s") + " below — a section that did not draft, " +
        "or a cross-reference to a section that does not exist."]);
    }
    if (openGaps.length) {
      rows.push(["Still missing", openGaps.map(function (g) { return g.clause; }).join(", ") +
        " — the check flagged " + (openGaps.length === 1 ? "this" : "these") +
        " and could not add " + (openGaps.length === 1 ? "it" : "them") + " automatically."]);
    }
    if (problems.length) {
      rows.push(["Worth a look", problems.length + " point" + (problems.length === 1 ? "" : "s") +
        " where the draft may not hold up. Listed below — these are judgement calls, " +
        "not errors, so nothing was changed."]);
    }
    var fm = _egRun().frontMatter;
    rows.push(["What gets inserted",
      (fm ? "Title, preamble and recitals, then " : "No title or preamble (drafting them failed) — just ") +
      sections.length + " numbered clause" + (sections.length === 1 ? "" : "s") +
      ", then a signature block. Appended at the end of the open document."]);
    rows.push(["What this does not do",
      "The signature block is a form with blanks — no names, titles or dates. " +
      "Placeholders are not filled, and your house styles are not applied."]);

    var panel = '<div class="_eg_verify_panel">' +
      '<div class="_eg_verify_head">Before this is inserted</div>' +
      rows.map(function (r) {
        return '<div class="_eg_verify_row">' +
          '<div class="_eg_verify_k">' + _esc(r[0]) + '</div>' +
          '<div class="_eg_verify_v">' + _esc(r[1]) + '</div>' +
        '</div>';
      }).join("") +
    '</div>';

    var issueHtml = "";
    if (chk.issues.length) {
      var ordered = chk.issues.slice().sort(function (a, b) {
        return (a.severity === "blocker" ? 0 : 1) - (b.severity === "blocker" ? 0 : 1);
      });
      issueHtml = '<div class="_eg_section_label">DOCUMENT CHECKS (' + chk.issues.length + ')</div>' +
        ordered.map(function (x) {
          return '<div class="_eg_dc_row _eg_dc_' + x.severity + '">' +
            '<span class="_eg_dc_tag">' + _esc(DC_KIND_LABEL[x.kind] || x.kind) + '</span>' +
            '<div class="_eg_dc_what">' + _esc(x.what) +
              (x.where ? ' <span class="_eg_dc_where">— ' + _esc(x.where) + '</span>' : '') +
            '</div>' +
            (x.detail ? '<div class="_eg_dc_detail">' + _esc(x.detail) + '</div>' : '') +
          '</div>';
        }).join("");
    }

    var auditHtml = "";
    if (problems.length || openGaps.length) {
      auditHtml = '<div class="_eg_section_label">READING IT BACK (' +
        (problems.length + openGaps.length) + ')</div>' +
        openGaps.map(function (g) {
          return '<div class="_eg_dc_row _eg_dc_warn">' +
            '<span class="_eg_dc_tag">Missing</span>' +
            '<div class="_eg_dc_what">' + _esc(g.clause) +
              (g.why ? ' — ' + _esc(g.why) : '') + '</div>' +
          '</div>';
        }).join("") +
        problems.map(function (p) {
          return '<div class="_eg_dc_row _eg_dc_warn">' +
            '<span class="_eg_dc_tag">' + _esc(p.severity || "medium") + '</span>' +
            '<div class="_eg_dc_what">' + _esc(p.what) +
              (p.where ? ' <span class="_eg_dc_where">— ' + _esc(p.where) + '</span>' : '') +
            '</div>' +
          '</div>';
        }).join("");
    }

    // The gate is the ACTION ROW, not the panel above it. This screen is
    // the end of the run and the one thing left to do is press Insert —
    // landing at the top of a long list of findings and leaving the reader
    // to scroll for the button is how "check it over" appeared to lead
    // nowhere. Scrolled to with "end", so the findings immediately above
    // it are on screen with it.
    return _bodyHeader() + _stageStrip() + panel + issueHtml + auditHtml +
      '<div class="_eg_actions_row _eg_actions_sticky" id="_eg_gate">' +
        '<button id="_eg_verify_back" type="button" class="_eg_btn_secondary">← Back to sections</button>' +
        '<button id="_eg_verify_read" type="button" class="_eg_btn_secondary">📄 Read the full draft</button>' +
        // The ONE button in the whole run that writes to the document, and
        // the only screen that does not move on by itself. It says what it
        // does rather than how many sections it does it to, because the
        // count was on the previous screen's button too and that is what
        // made it read as the same action twice.
        '<button id="_eg_verify_insert" type="button" class="_eg_btn_primary _eg_btn_apply _eg_btn_final">' +
          'Insert into the document →</button>' +
      '</div>';
  }

  function _wireDraftVerifyControls(body) {
    var back = body.querySelector("#_eg_verify_back");
    if (back) back.onclick = function () {
      _egRun().status = "draft_review";
      _renderOverlayBody();
    };
    var ins = body.querySelector("#_eg_verify_insert");
    if (ins) ins.onclick = function () { _insertAcceptedDraftSections(); };
    var read = body.querySelector("#_eg_verify_read");
    if (read) read.onclick = function () {
      // The last chance to read it whole, so the dialog inserts from here.
      _openDraftPreview({ label: "Insert into the document →",
        onGo: function () { _insertAcceptedDraftSections(); } });
    };
  }

  // Review -> checks -> verify. The deterministic check runs first because
  // it is instant and its findings sharpen what the audit is looking at.
  function _runDraftChecks() {
    if (!_egRun()) return Promise.resolve();
    var sections = (_egRun().outline || []).filter(function (s) {
      return (_egRun().draftAcceptance[s.id] || "accept") === "accept";
    });
    _egRun().draftCheck = _dcCheck(sections, _dtName());
    return _runDraftAudit().then(function () {
      if (!_egRun()) return;
      // Re-run the deterministic check: the audit may have added sections,
      // and a check that describes the pre-gapfill draft is worse than none.
      var after = (_egRun().outline || []).filter(function (s) {
        return (_egRun().draftAcceptance[s.id] || "accept") === "accept";
      });
      _egRun().draftCheck = _dcCheck(after, _dtName());
      _egRun().status = "draft_verify";
      var chk = _egRun().draftCheck || { blockers: 0, warnings: 0 };
      _stream(chk.blockers ? "warn" : "ok", "Document checks",
        chk.blockers ? chk.blockers + " to fix before inserting"
                     : (chk.warnings ? chk.warnings + " worth a look" : "nothing blocking"));
      _renderOverlayBody();
    });
  }
  // ─── [/DRAFT-VERIFY-UI] ───────────────────────────────────────────

  // ─── [DRAFT-AUDIT] ────────────────────────────────────────────────
  // Two questions the per-section drafting cannot answer, because each
  // section was written without seeing the others:
  //
  //   COVERAGE  — is anything MISSING? Omission is this agent's signature
  //               failure: a polished, correctly-formatted agreement with no
  //               limitation of liability reads fine and nobody notices.
  //   AUDIT     — read cold, as if the other side sent it: does it still
  //               protect us, and do the sections contradict each other?
  //
  // Both run on the assembled draft, and both are scored against ELI's
  // guidance rather than general drafting taste. Rounds stop at clean or at
  // DRAFT_AUDIT_MAX — the same rule as the revise agent, and for the same
  // reason: a check that can never come clean just burns the user's time.
  // TO REMOVE: delete to [/DRAFT-AUDIT] + _runDraftAudit's callers.
  var DRAFT_AUDIT_MAX = 4;

  function _daAssembled(sections) {
    return (sections || []).filter(function (s) {
      return s && String(s.content || "").trim();
    }).map(function (s) {
      return "§" + (s.num || "?") + " " + (s.name || "") + "\n" + String(s.content || "");
    }).join("\n\n");
  }

  function _daGuidanceBlock(playbooks, guidance) {
    var lines = [];
    (guidance || []).slice(0, 20).forEach(function (g) {
      lines.push("- (" + (g.tier || "default") + ") " + g.text);
    });
    (playbooks || []).slice(0, 20).forEach(function (p) {
      if (p.locked) lines.push("- (locked) " + p.clauseName + " language must not be altered.");
      if (p.guidance) lines.push("- (" + p.clauseName + ") " + p.guidance);
    });
    return lines.length ? "\n═══ ELI'S POSITIONS ═══\n" + lines.join("\n") : "";
  }

  function _buildDraftAuditPrompt(active, round, previousGaps) {
    var iv = active.interview || {};
    var sections = (active.outline || []).filter(function (s) {
      return (active.draftAcceptance[s.id] || "accept") === "accept";
    });
    var prior = (previousGaps && previousGaps.length)
      ? "\n═══ WHAT THE LAST ROUND SAID WAS MISSING ═══\n" +
        previousGaps.map(function (g) { return "- " + g; }).join("\n") +
        "\nThose should now be addressed. Do not repeat one that is."
      : "";
    var dt = _dtFor(iv.agreementType);
    var unit = dt.body === "numbered-clauses" ? "clause" : "part";
    return [
      "You are a senior attorney reading a draft " + dt.label.toLowerCase() +
        " your own team produced.",
      dt.closing === "execution-block" || dt.closing === "consent-block"
        ? "Read it as if the other side had just sent it to you."
        : "Read it as the person it is addressed to will read it.",
      "",
      "Answer TWO questions:",
      "1. COVERAGE — what is MISSING that a " + dt.label.toLowerCase() +
        " of this kind must have?",
      "   This matters more than anything else here: a missing " + unit + " reads as",
      "   a clean document, and nobody notices it until it is needed.",
      "2. PROBLEMS — where do parts contradict each other, leave a gap, or",
      "   take a position ELI's guidance says not to take?",
      "",
      "Rules:",
      "- Judge against ELI's positions below where they cover the point. Where",
      "  they do not, say so rather than inventing a house position.",
      "- Only report what is ACTUALLY absent or wrong. Do not list improvements",
      "  you would merely prefer — that is what makes an audit useless.",
      "- A missing " + unit + " this kind of document does not need is not a gap.",
      "- What a " + dt.label.toLowerCase() + " conventionally contains: " + dt.sections + ".",
      "",
      "Return JSON only:",
      "{",
      '  "gaps": [ {"clause":"Limitation of Liability","why":"<one sentence>","severity":"high|medium|low"} ],',
      '  "problems": [ {"where":"§4","what":"<one sentence>","severity":"high|medium|low"} ],',
      '  "clean": false',
      "}",
      "clean: true ONLY when gaps and problems are both empty.",
      "",
      "═══ DOCUMENT ═══",
      (iv.agreementType || "(unspecified)") + " — a " + dt.label.toLowerCase() + ".",
      "",
      "═══ WHAT THE CLIENT ASKED FOR ═══",
      JSON.stringify({ seed: iv.seed, turns: iv.turns }, null, 1).slice(0, 3000),
      _daGuidanceBlock(active.playbooks, active.guidance),
      prior,
      "",
      "═══ ROUND " + round + " OF AT MOST " + DRAFT_AUDIT_MAX + " ═══",
      "",
      "═══ THE DRAFT ═══",
      _daAssembled(sections),
    ].filter(Boolean).join("\n");
  }

  // Merge a round's findings, deduped. The same gap named twice across
  // rounds is one gap; saying it twice is what made the revise agent's
  // follow-up read like four problems when it had two.
  function _daMergeFindings(existing, round) {
    var out = (existing || []).slice();
    var seen = {};
    out.forEach(function (x) { seen[_dcNorm(x.clause || x.where || x.what)] = true; });
    ((round && round.gaps) || []).forEach(function (g) {
      var k = _dcNorm(g.clause || g.why);
      if (!k || seen[k]) return;
      seen[k] = true;
      out.push({ kind: "gap", clause: g.clause || "", why: g.why || "",
        severity: g.severity || "medium" });
    });
    ((round && round.problems) || []).forEach(function (p) {
      var k = _dcNorm((p.where || "") + " " + (p.what || ""));
      if (!k || seen[k]) return;
      seen[k] = true;
      out.push({ kind: "problem", where: p.where || "", what: p.what || "",
        severity: p.severity || "medium" });
    });
    return out;
  }

  function _daRoundClean(r) {
    if (!r) return false;
    var g = (r.gaps || []).length, p = (r.problems || []).length;
    // The model's own `clean` boolean is advisory; what it actually returned
    // is the fact. The revise agent ran eight rounds against a clean verdict
    // because those two disagreed.
    return g === 0 && p === 0;
  }

  // A gap the audit found becomes a real section: resolved through the same
  // retrieval ladder, drafted, and numbered after the last one. Reporting
  // "you are missing a limitation of liability" and leaving it missing would
  // be a worse outcome than not checking.
  function _daDraftGaps(gaps) {
    if (!_egRun() || !gaps.length) return Promise.resolve(0);
    var sources = {
      playbooks: _egRun().playbooks || [],
      cards: _dtFor(_dtName()).retrieval ? (_egRun().clauseCards || []) : [],
      docType: _dtName(),
    };
    var maxNum = 0;
    (_egRun().outline || []).forEach(function (s) {
      var n = parseInt(s.num, 10);
      if (!isNaN(n) && n > maxNum) maxNum = n;
    });
    var added = [];
    gaps.forEach(function (g) {
      if (!g.clause) return;
      maxNum++;
      var id = "gap" + maxNum + "_" + _dcNorm(g.clause).replace(/\s+/g, "_").slice(0, 24);
      var sec = { id: id, num: String(maxNum), name: g.clause,
        focus: g.why || ("Added because the audit found it missing."),
        status: "queued", content: "", _fromAudit: true };
      _egRun().outline.push(sec);
      _egRun().draftAcceptance[id] = "accept";
      added.push(sec);
    });
    if (!added.length) return Promise.resolve(0);

    var resolved = _retResolveAll(added, sources);
    resolved.forEach(function (r) { if (r.id) _egRun().retrieval[r.id] = r; });

    var needsAi = [];
    added.forEach(function (s) {
      var r = _egRun().retrieval[s.id];
      if (r && (r.tier === "locked" || r.tier === "playbook" || r.tier === "template") && r.text) {
        s.content = String(r.text).trim();
        s.source = r.tier;
        s.provenance = r.provenance;
        s.status = "done";
        return;
      }
      s.source = (r && r.tier) || "generate";
      s.provenance = (r && r.provenance) || "";
      s.status = "drafting";
      needsAi.push(s);
    });
    _renderOverlayBody();
    if (!needsAi.length) return Promise.resolve(added.length);

    var next = 0;
    function one() {
      if (next >= needsAi.length) return Promise.resolve();
      var s = needsAi[next++];
      return _aiTextCall(_buildSectionDraftPrompt(_egRun(), s))
        .then(function (text) {
          s.content = String(text || "").trim();
          s.status = "done";
          _renderOverlayBody();
        }).catch(function (err) {
          s.status = "failed";
          s.content = "(drafting failed: " + (err && err.message) + ")";
          _renderOverlayBody();
        }).then(one);
    }
    var run = [];
    for (var w = 0; w < Math.min(2, needsAi.length); w++) run.push(one());
    return Promise.all(run).then(function () {
      // The report has to keep up, or the reuse figure describes a draft
      // that no longer exists.
      _egRun().retrievalReport = _retReport(
        (_egRun().outline || []).map(function (x) { return _egRun().retrieval[x.id]; })
          .filter(Boolean));
      return added.length;
    });
  }

  function _runDraftAudit() {
    if (!_egRun()) return Promise.resolve(null);
    _egRun().status = "draft_audit";
    _egRun().auditRounds = [];
    _egRun().auditFindings = [];
    _egRun().auditRound = 1;
    _renderOverlayBody();

    function step(round) {
      if (!_egRun()) return Promise.resolve(null);
      if (round > DRAFT_AUDIT_MAX) return Promise.resolve(null);
      _egRun().auditRound = round;
      _stream("stage", "Reading the draft back, round " + round,
        "what is missing, and does it still protect us");
      _renderOverlayBody();
      var openGaps = _egRun().auditFindings.filter(function (f) { return f.kind === "gap"; })
        .map(function (f) { return f.clause; });
      return _aiJsonCall(_buildDraftAuditPrompt(_egRun(), round, openGaps),
        { gaps: "object", problems: "object" })
        .then(function (r) {
          if (!_egRun()) return null;
          var clean = _daRoundClean(r);
          var before = _egRun().auditFindings.length;
          _egRun().auditFindings = _daMergeFindings(_egRun().auditFindings, r);
          var fresh = _egRun().auditFindings.length - before;
          _egRun().auditRounds.push({
            round: round, clean: clean,
            gaps: ((r && r.gaps) || []).length,
            problems: ((r && r.problems) || []).length,
            drafted: 0,
          });
          _stream(clean ? "ok" : "found",
            clean ? "Round " + round + " — nothing missing"
                  : "Round " + round + " — " + ((r && r.gaps) || []).length + " gap(s), " +
                    ((r && r.problems) || []).length + " problem(s)",
            fresh ? fresh + " new since the last round" : "nothing new since the last round");
          _renderOverlayBody();
          if (clean) return null;
          // A round that found nothing NEW has nothing left to say; going
          // again would re-report the same findings against the same text.
          if (!fresh) return null;
          // Draft what is missing, then look again at the document that now
          // includes it. Problems are reported rather than fixed — a wrong
          // position is a decision for the reader, not an omission to patch.
          var gaps = ((r && r.gaps) || []).filter(function (g) {
            return g && g.clause && (g.severity === "high" || g.severity === "medium");
          });
          if (!gaps.length) return null;
          _egRun().status = "draft_gapfill";
          _stream("stage", "Drafting what was missing",
            gaps.map(function (g) { return g.clause; }).join(", "));
          _renderOverlayBody();
          return _daDraftGaps(gaps).then(function (n) {
            var last = _egRun().auditRounds[_egRun().auditRounds.length - 1];
            if (last) last.drafted = n;
            _egRun().status = "draft_audit";
            if (!n) return null;
            return step(round + 1);
          });
        })
        .catch(function () { return null; });
    }
    return step(1).then(function () {
      if (!_egRun()) return null;
      _egRun().status = "draft_verify";
      _renderOverlayBody();
      return _egRun().auditFindings;
    });
  }
  // ─── [/DRAFT-AUDIT] ───────────────────────────────────────────────

  // ─── [STRUCTURE] ──────────────────────────────────────────────────
  // The full clause list for the agreement, settled BEFORE a word is
  // drafted, and audited for completeness several times over.
  //
  // Auditing after drafting was the wrong order: by then a missing clause
  // costs a re-draft, and the reader has already read twelve sections that
  // look finished. A structure is cheap to fix and cheap to check, so the
  // checking happens here and happens repeatedly.
  //
  // Three inputs decide what "comprehensive" means, in this order:
  //   1. the clause library — what OUR OWN agreements of this type contain,
  //      in the order they contain it. This is the strongest signal and it
  //      is why the indexer exists.
  //   2. the playbook — clauses we have a position on.
  //   3. the agreement type's own requirements, including the ones the
  //      intake answers create (a three-way NDA needs clauses a two-way one
  //      has no reason to have).
  // TO REMOVE: delete to [/STRUCTURE] + _runStructurePhase's callers.
  var STRUCTURE_AUDIT_MAX = 3;
  var STRUCTURE_MIN_SECTIONS = 8;

  // What our own agreements of this type actually contain, in document
  // order. Straight from the clause index — no model involved.
  function _stLibraryShape(cards, docType) {
    var rows = (cards || []).filter(function (c) {
      return c && c.heading && (!docType || _typeMatches(c.agreementType || "", docType));
    });
    if (!rows.length) return [];
    var byTpl = {};
    rows.forEach(function (c) {
      var k = c.templateId || "_";
      (byTpl[k] = byTpl[k] || []).push(c);
    });
    // The template with the most clauses is the fullest example of the type.
    var best = null;
    Object.keys(byTpl).forEach(function (k) {
      if (!best || byTpl[k].length > best.length) best = byTpl[k];
    });
    return (best || []).slice().sort(function (a, b) {
      return (a.order || 0) - (b.order || 0);
    }).map(function (c) { return c.heading; });
  }

  function _stPlaybookNames(playbooks) {
    return (playbooks || []).map(function (p) { return p.clauseName; })
      .filter(Boolean);
  }

  function _buildStructurePrompt(active) {
    var iv = active.interview || {};
    var dt = _dtFor(iv.agreementType);
    var shape = _stLibraryShape(active.clauseCards, iv.agreementType);
    var pb = _stPlaybookNames(active.playbooks);
    return [
      "You are a senior lawyer setting out the FULL structure of a " +
        dt.label.toLowerCase() + ", before any drafting starts.",
      "",
      "This must be COMPREHENSIVE. A real " + dt.label.toLowerCase() + " of this",
      "kind, not a summary of one. Err heavily toward including a section: one",
      "nobody needs costs a deletion, one that is missing costs a renegotiation.",
      "Typical length: " + dt.range + ". Fewer than " + dt.min + " is certainly wrong.",
      "",
      "Include, where this kind of document calls for them: " + dt.sections + ",",
      "and anything the intake answers specifically create.",
      "",
      // Only a document with parties can have the multi-party problem. A
      // memo told to consider joint and several liability produces sections
      // nobody asked for.
      (dt.closing === "execution-block" || dt.closing === "consent-block")
        ? [
          "WHAT THE PARTIES ARE CHANGES THE STRUCTURE. If more than two parties are",
          "involved, it needs sections a two-party one never has to answer:",
          "whether obligations run between EVERY pair of parties or only through one",
          "hub; whether a party may disclose another party's information to the",
          "third; whether liability is joint, several, or joint and several; how a",
          "party is added or removed; whether consent means all parties or only the",
          "affected ones; and how notices reach every party. Do not skip these.",
          "",
        ].join("\n")
        : "",
      "Return JSON only:",
      "{",
      '  "sections": [',
      '    {"num":"1","name":"Definitions","focus":"<1-2 sentences: what goes in it>",',
      '     "required":true,"because":"<why this document needs it>"}',
      "  ]",
      "}",
      "",
      "RULES:",
      "1. " + _dtExcluded(dt),
      "2. Number them 1..N in the order they should appear.",
      "3. `required` false only for a part that is genuinely optional here.",
      // A letter's sections are scaffolding for drafting, not headings the
      // reader will see, so naming them "Section 4" defeats the point.
      _dtFor(iv.agreementType).body === "prose"
        ? "4. These are not headings — this document reads as continuous prose.\n" +
          "   Name each one for what that stretch of it does, so the drafter knows\n" +
          "   what to write; the reader never sees the names."
        : "",
      "",
      "═══ DOCUMENT ═══",
      (iv.agreementType || "(not specified)") + " — a " + dt.label.toLowerCase() + ".",
      "",
      "═══ WHAT THE CLIENT ASKED FOR ═══",
      JSON.stringify({ seed: iv.seed, turns: iv.turns }, null, 1),
      shape.length
        ? "\n═══ HOW OUR OWN DOCUMENTS OF THIS TYPE ARE STRUCTURED ═══\n" +
          shape.map(function (n, i) { return (i + 1) + ". " + n; }).join("\n") +
          "\nThis is the house structure. Follow it closely, in this order, and" +
          " ADD what this particular matter needs on top of it."
        : "",
      pb.length
        ? "\n═══ CLAUSES ELI HAS A POSITION ON ═══\n" + pb.join(", ") +
          "\nInclude every one of these that belongs in this kind of document."
        : "",
    ].filter(Boolean).join("\n");
  }

  // The completeness check. Runs against the STRUCTURE, several times, and
  // adds what is missing — no drafting has happened yet, so this is cheap.
  function _buildStructureAuditPrompt(active, round, alreadyAdded) {
    var iv = active.interview || {};
    var names = (active.outline || []).map(function (s) {
      return s.num + ". " + s.name;
    }).join("\n");
    var dt = _dtFor(iv.agreementType);
    var unit = dt.body === "numbered-clauses" ? "clause" : "part";
    return [
      "You are reviewing the STRUCTURE of a " + dt.label.toLowerCase() + " before",
      "it is drafted. Your only question: WHAT IS MISSING?",
      "",
      "A missing " + unit + " is invisible once the document is drafted — it reads",
      "as a clean " + dt.label.toLowerCase() + " and nobody notices until it is",
      "needed. Catching it here costs nothing; catching it later costs far more.",
      "",
      "Be demanding. Check specifically for:",
      // Boilerplate only matters where there is boilerplate. Telling a memo
      // it is missing counterparts is the noise this branch avoids.
      dt.body === "numbered-clauses"
        ? "- boilerplate that is quietly absent (waiver, severability, counterparts,\n" +
          "  amendment, assignment, notices, entire agreement)\n" +
          "- protections a party would expect (limitation of liability, indemnity,\n" +
          "  remedies, injunctive relief, survival, insurance)"
        : "- anything the reader will need that is assumed rather than stated",
      "- parts the SPECIFIC facts require — who it is addressed to, what is being",
      "  asked or exchanged, the jurisdictions involved, regulated subject matter",
      "- what a " + dt.label.toLowerCase() + " conventionally contains: " + dt.sections,
      "",
      "Do NOT propose renaming or reordering. Only what is ABSENT.",
      "Do NOT pad it. A " + dt.label.toLowerCase() + " that should run to " +
        dt.range + " is not improved by reaching twice that.",
      "",
      "Return JSON only:",
      "{",
      '  "missing": [ {"name":"Survival","after":"Termination","why":"<one sentence>",',
      '                "severity":"high|medium|low"} ],',
      '  "complete": false',
      "}",
      "complete: true only when `missing` is empty.",
      "",
      "═══ DOCUMENT ═══",
      (iv.agreementType || "(not specified)") + " — a " + dt.label.toLowerCase() + ".",
      "",
      "═══ WHAT THE CLIENT ASKED FOR ═══",
      JSON.stringify({ seed: iv.seed, turns: iv.turns }, null, 1).slice(0, 2500),
      alreadyAdded && alreadyAdded.length
        ? "\n═══ ALREADY ADDED BY EARLIER ROUNDS ═══\n" + alreadyAdded.join(", ") +
          "\nDo not propose any of these again."
        : "",
      "",
      "═══ ROUND " + round + " OF AT MOST " + STRUCTURE_AUDIT_MAX + " ═══",
      "",
      "═══ THE STRUCTURE SO FAR (" + (active.outline || []).length + " " + unit + "s) ═══",
      names,
    ].filter(Boolean).join("\n");
  }

  // Insert a missing clause after the one it names, or at the end. Numbers
  // are rewritten afterwards so they stay 1..N.
  function _stInsertMissing(outline, miss) {
    var at = outline.length;
    if (miss.after) {
      for (var i = 0; i < outline.length; i++) {
        if (_dcNorm(outline[i].name) === _dcNorm(miss.after)) { at = i + 1; break; }
      }
    }
    outline.splice(at, 0, {
      id: "add_" + _dcNorm(miss.name).replace(/\s+/g, "_").slice(0, 28) + "_" + outline.length,
      num: "0",
      name: miss.name,
      focus: miss.why || "Added by the structure check.",
      required: miss.severity !== "low",
      status: "queued",
      content: "",
      _addedByAudit: true,
    });
    return at;
  }

  function _stRenumber(outline) {
    (outline || []).forEach(function (s, i) { s.num = String(i + 1); });
    return outline;
  }

  // Already present? Name match is enough here — the audit proposes clause
  // names, and a near-duplicate is worse than a miss.
  function _stHas(outline, name) {
    var n = _dcNorm(name);
    if (!n) return true;
    return (outline || []).some(function (s) {
      var m = _dcNorm(s.name);
      return m === n || m.indexOf(n) !== -1 || n.indexOf(m) !== -1;
    });
  }
  // ─── [/STRUCTURE] ─────────────────────────────────────────────────

  // ─── [FRONT-MATTER] ───────────────────────────────────────────────
  // The parts of an agreement that are not clauses: the title, the preamble
  // naming the parties and the date, the recitals, and the execution block.
  //
  // The structure pass is told to leave these out — a numbered clause list
  // is not the place for "WHEREAS" — and for one build nothing picked them
  // up, so the draft began at "1. Definitions" and ended mid-sentence. This
  // is the separate handling that was promised.
  //
  // Party names come back as [[Placeholders]] unless the intake actually
  // named them. Inventing a legal entity name is worse than leaving a blank
  // somebody has to fill.
  // TO REMOVE: delete to [/FRONT-MATTER] + _runFrontMatter's caller.

  function _buildFrontMatterPrompt(active) {
    var iv = active.interview || {};
    var pre = (active.clauseCards || []).filter(function (c) {
      return c && /^preamble$/i.test(String(c.heading || "")) &&
        (!iv.agreementType || _typeMatches(c.agreementType || "", iv.agreementType));
    })[0];
    var dt = _dtFor(iv.agreementType);
    var open = _fmOpeningSpec(dt);
    var close = _fmClosingSpec(dt);
    if (!open.fields.length && !close.fields.length) return "";
    return [
      "Draft the parts of a " + dt.label.toLowerCase() + " that are not its body:",
      open.what + (close.what ? " " + close.what : ""),
      "The body is handled separately — do not draft it here.",
      "",
      "Return JSON only, with EXACTLY these fields:",
      "{",
      open.fields.concat(close.fields).join("\n"),
      "}",
      "",
      "RULES:",
      "1. Use [[Double Bracket Placeholders]] for anything the intake did not",
      "   actually state: legal names, entity types, jurisdictions of",
      "   incorporation, addresses, dates, job titles. NEVER invent a party",
      "   name, a company number, an address or a signatory.",
      open.rules.concat(close.rules).map(function (r, i) {
        return (i + 2) + ". " + r;
      }).join("\n"),
      "",
      "═══ DOCUMENT ═══",
      (iv.agreementType || "(not specified)") + " — a " + dt.label.toLowerCase() + ".",
      "",
      "═══ WHAT THE CLIENT ASKED FOR ═══",
      JSON.stringify({ seed: iv.seed, turns: iv.turns }, null, 1),
      // Only a contract-shaped document has a preamble to learn from, and
      // the card library is only consulted for types that draw on it.
      dt.frontMatter === "contract" && pre && pre.text
        ? "\n═══ HOW OUR OWN DOCUMENTS OF THIS TYPE OPEN ═══\n" +
          String(pre.text).slice(0, 1200) +
          "\nFollow this form. Replace its specifics with placeholders."
        : "",
    ].filter(Boolean).join("\n");
  }

  // What opens this kind of document: the JSON fields the model must return
  // and the rules for them. Paired one-to-one with _fmLayout's shapes — if
  // you add a shape there, add its spec here or the layout reads undefined.
  function _fmOpeningSpec(dt) {
    if (dt.frontMatter === "letter") {
      return {
        what: "the date, the addressee block, the subject line and the salutation.",
        fields: [
          '  "date": "[[Date]]",',
          '  "addressee": ["[[Recipient Name]]", "[[Title]]", "[[Company]]", "[[Address]]"],',
          '  "title": "Notice of Termination — Master Services Agreement dated [[Date]]",',
          '  "salutation": "Dear [[Recipient Name]]:",',
        ],
        rules: [
          "`title` is the Re: line — what this letter is about, in sentence case," +
            " naming the agreement or matter it concerns. Not a contract title in capitals.",
          "`addressee` is one array entry per line of the address block.",
          "The salutation is formal and ends with a colon.",
        ],
      };
    }
    if (dt.frontMatter === "memo") {
      return {
        what: "the memorandum header.",
        fields: [
          '  "to": "[[Recipient]]",',
          '  "from": "[[Author]]",',
          '  "date": "[[Date]]",',
          '  "title": "Whether the indemnity in the Lipotype MSA covers third-party IP claims",',
          '  "privilege": "PRIVILEGED AND CONFIDENTIAL — ATTORNEY WORK PRODUCT",',
        ],
        rules: [
          "`title` is the RE: line — the question this memo answers, stated as a" +
            " question or a proposition, not a topic label.",
          "Keep the privilege legend unless the intake said this memo is not privileged.",
        ],
      };
    }
    if (dt.frontMatter === "email") {
      return {
        what: "the subject line and the greeting.",
        fields: [
          '  "title": "MSA renewal — the two points still open",',
          '  "salutation": "Hi [[Recipient Name]],",',
        ],
        rules: [
          "The subject says what the reader must know or do, in under ten words.",
          "The greeting matches how colleagues actually write to each other — no" +
            " \"Dear Sir or Madam\" in an internal email.",
        ],
      };
    }
    if (dt.frontMatter === "none") return { what: "", fields: [], rules: [] };
    return {
      what: "its title, its preamble naming the parties, and its recitals.",
      fields: [
        '  "title": "MUTUAL NON-DISCLOSURE AGREEMENT",',
        '  "preamble": "This Mutual Non-Disclosure Agreement (this \\"Agreement\\") is entered into as of [[Effective Date]] by and between ...",',
        '  "recitals": ["WHEREAS, the Parties wish to explore a potential business relationship;"],',
        '  "nowTherefore": "NOW, THEREFORE, in consideration of the mutual covenants set out below, the Parties agree as follows:",',
      ],
      rules: [
        "Name EVERY party. If three parties are involved, all three appear in" +
          " the preamble and each gets a defined label.",
        "Recitals: 2-4 WHEREAS clauses explaining why the parties are doing" +
          " this. Each ends with a semicolon, including the last, because" +
          " nowTherefore follows it.",
        "The title is what the document is, in capitals.",
        "The preamble defines the short form: (this \"Agreement\"), and gives" +
          " each party its defined label — that label is what the clauses use.",
      ],
    };
  }

  // What closes it. Same pairing rule as _fmOpeningSpec, against
  // _fmSignatureLayout.
  function _fmClosingSpec(dt) {
    if (dt.closing === "signoff") {
      return {
        what: "the sign-off.",
        fields: [
          '  "signoff": "Yours sincerely,",',
          '  "senderName": "[[Sender Name]]",',
          '  "senderTitle": "[[Sender Title]]"',
        ],
        rules: ["The sign-off matches the salutation's register."],
      };
    }
    if (dt.closing === "consent-block") {
      return {
        what: "the list of signatories.",
        fields: ['  "parties": [ {"name":"[[Director Name]]"} ]'],
        rules: ["One entry per signatory. If the intake did not name them," +
          " return placeholders — never invent a director."],
      };
    }
    if (dt.closing === "none") return { what: "", fields: [], rules: [] };
    return {
      what: "the parties who sign it.",
      fields: ['  "parties": [ {"label":"Discloser","name":"[[Party 1 Legal Name]]"} ]'],
      rules: ["Every party in the preamble appears in `parties`, with the same" +
        " defined label."],
    };
  }

  // Front matter -> the same {text, kind, indent} shape the clause layout
  // produces, so insert handles all of it through one path.
  // One row helper, so every shape below produces the same {text, kind,
  // indent, listLevel, section} the insert path already understands.
  function _fmRow(text, kind, section) {
    return { text: String(text), kind: kind, indent: 0, listLevel: -1, section: section };
  }

  function _fmLayout(fm, docType) {
    if (!fm) return [];
    var shape = _dtFor(docType).frontMatter;
    if (shape === "none") return [];
    var out = [];
    var title = String(fm.title || "").trim();

    // A letter opens with a date and an addressee, not a title and a
    // preamble. Putting a contract's front matter on a notice is the most
    // visible way to get the document wrong.
    if (shape === "letter") {
      out.push(_fmRow(String(fm.date || "[[Date]]").trim(), "clause", "Date"));
      (Array.isArray(fm.addressee) ? fm.addressee : []).forEach(function (l) {
        var t = String(l || "").trim();
        if (t) out.push(_fmRow(t, "sigline", "Addressee"));
      });
      if (title) out.push(_fmRow(title, "reline", "Re"));
      out.push(_fmRow(String(fm.salutation || "Dear [[Recipient Name]]:").trim(),
        "clause", "Salutation"));
      return out;
    }

    if (shape === "memo") {
      out.push(_fmRow("MEMORANDUM", "title", "Title"));
      [["TO", fm.to], ["FROM", fm.from], ["DATE", fm.date], ["RE", title]]
        .forEach(function (p) {
          out.push(_fmRow(p[0] + ":\t" + String(p[1] || "[[" + p[0] + "]]").trim(),
            "sigline", "Header"));
        });
      // Privilege is a memo's most consequential line and the easiest to
      // forget, so it is part of the shape rather than left to the model.
      out.push(_fmRow(String(fm.privilege ||
        "PRIVILEGED AND CONFIDENTIAL — ATTORNEY WORK PRODUCT").trim(),
        "reline", "Header"));
      return out;
    }

    if (shape === "email") {
      out.push(_fmRow("Subject: " + (title || "[[Subject]]"), "reline", "Subject"));
      out.push(_fmRow(String(fm.salutation || "Hi [[Recipient Name]],").trim(),
        "clause", "Salutation"));
      return out;
    }

    // contract
    if (title) out.push(_fmRow(title, "title", "Title"));
    var pre = String(fm.preamble || "").trim();
    if (pre) out.push(_fmRow(pre, "clause", "Preamble"));
    var recitals = Array.isArray(fm.recitals) ? fm.recitals : [];
    if (recitals.length) {
      out.push(_fmRow("RECITALS", "heading", "Recitals"));
      recitals.forEach(function (r) {
        var t = String(r || "").trim();
        if (t) out.push(_fmRow(t, "clause", "Recitals"));
      });
    }
    var nt = String(fm.nowTherefore || "").trim();
    if (nt) out.push(_fmRow(nt, "clause", "Recitals"));
    return out;
  }

  // The execution block. Deliberately a skeleton: ELI fills in nothing it
  // was not told, and a signature block with invented names is worse than
  // one with blanks. The follow-up says it needs completing.
  function _fmSignatureLayout(fm, docType) {
    var d = _dtFor(docType);
    if (d.closing === "none") return [];
    var out = [];

    // A letter signs off; it does not execute. "IN WITNESS WHEREOF" under
    // a notice is the tell that a contract template was used for it.
    if (d.closing === "signoff") {
      out.push(_fmRow(String((fm && fm.signoff) || "Yours sincerely,").trim(),
        "clause", "Closing"));
      out.push(_fmRow("____________________________", "sigline", "Closing"));
      [String((fm && fm.senderName) || "[[Sender Name]]").trim(),
       String((fm && fm.senderTitle) || "[[Sender Title]]").trim()]
        .forEach(function (l) { out.push(_fmRow(l, "sigline", "Closing")); });
      return out;
    }

    if (d.closing === "consent-block") {
      out.push(_fmRow("IN WITNESS WHEREOF, the undersigned have executed this " +
        "consent as of the date first written above.", "clause", "Execution"));
      var signers = (fm && Array.isArray(fm.parties) && fm.parties.length)
        ? fm.parties : [{ name: "[[Director Name]]" }, { name: "[[Director Name]]" }];
      signers.forEach(function (p) {
        out.push(_fmRow("____________________________", "sigline", "Execution"));
        out.push(_fmRow(String((p && p.name) || "[[Director Name]]").trim(),
          "partyname", "Execution"));
        out.push(_fmRow("Director", "sigline", "Execution"));
      });
      return out;
    }

    // execution-block
    var parties = (fm && Array.isArray(fm.parties) && fm.parties.length)
      ? fm.parties
      : [{ label: "", name: "[[Party 1 Legal Name]]" },
         { label: "", name: "[[Party 2 Legal Name]]" }];
    out.push(_fmRow("IN WITNESS WHEREOF, the Parties have executed this " +
      (d.label === "Agreement" ? (docType || "Agreement") : d.label) +
      " as of the date first written above.", "clause", "Execution"));
    parties.forEach(function (p) {
      var name = String((p && p.name) || "").trim() || "[[Party Legal Name]]";
      out.push(_fmRow(name, "partyname", "Execution"));
      ["By: ____________________________", "Name:", "Title:", "Date:"].forEach(function (l) {
        out.push(_fmRow(l, "sigline", "Execution"));
      });
    });
    return out;
  }

  function _runFrontMatter() {
    if (!_egRun()) return Promise.resolve(null);
    var prompt = _buildFrontMatterPrompt(_egRun());
    // A policy has neither an opening nor a closing, so there is nothing to
    // ask for. Spending a call to be told so is waste, not safety.
    if (!prompt) { _egRun().frontMatter = null; return Promise.resolve(null); }
    return _aiJsonCall(prompt,
      { title: "string", preamble: "string", recitals: "object",
        date: "string", addressee: "object", salutation: "string",
        to: "string", from: "string", privilege: "string",
        signoff: "string", senderName: "string", senderTitle: "string",
        parties: "object" })
      .then(function (r) {
        if (!_egRun()) return null;
        _egRun().frontMatter = r || null;
        return r;
      })
      .catch(function () {
        // A draft with clauses and no preamble is still useful; one that
        // failed entirely because the recitals call timed out is not.
        if (_egRun()) _egRun().frontMatter = null;
        return null;
      });
  }

  // Placeholders anywhere in the front matter, for the follow-up.
  function _fmPlaceholders(fm) {
    if (!fm) return [];
    var text = [fm.title, fm.preamble, fm.nowTherefore, fm.date, fm.salutation,
      fm.to, fm.from, fm.senderName, fm.senderTitle]
      .concat(Array.isArray(fm.recitals) ? fm.recitals : [])
      .concat(Array.isArray(fm.addressee) ? fm.addressee : [])
      .concat((Array.isArray(fm.parties) ? fm.parties : []).map(function (p) {
        return (p && p.name) || "";
      })).join("\n");
    return _dcPlaceholders(text);
  }
  // ─── [/FRONT-MATTER] ──────────────────────────────────────────────

  // ─── [DRAFT-LAYOUT] ───────────────────────────────────────────────
  // Turns drafted sections into the paragraph list a contract is actually
  // made of: numbered section headings, numbered clauses beneath them, and
  // indented sub-items — rather than a run of undifferentiated prose.
  //
  // The numbering is LITERAL, written into the text, not Word list
  // numbering. Word's auto-numbering is what made the clause indexer need
  // three different heading detectors, it renumbers the whole document when
  // something upstream changes, and it does not survive being pasted
  // elsewhere. A contract whose numbers are in the text reads correctly
  // everywhere and can be read back by ELI later.
  // TO REMOVE: delete to [/DRAFT-LAYOUT] + _diLayout's caller in insert.

  // Numbering the model wrote for itself. Stripped, so a clause does not
