  var RE_DI_LEADNUM = new RegExp(
    "^\\s*(?:\\u00a7\\s*)?(?:\\d+(?:\\.\\d+)*\\s*[.)]?\\s+|\\((?:[a-z]|[ivx]{1,4}|\\d{1,2})\\)\\s+|[-\\u2022]\\s+)",
