    // it, and nothing is numbered — a memo's sections are not clauses.
    // `subhead` rather than `heading` because a contract's headings are
    // centred and a memo's are not.
    if (shape === "headed-sections") {
      var hs = [];
      (sections || []).forEach(function (s) {
        if (!s) return;
