  // Points of left indent per level. Modest — a contract is indented, not
  // staircased, and deep indents wrap badly in a narrow column.
  var DI_INDENT_PT = [0, 18, 36];
  function _diIndentPt(level) {
    var i = Math.max(0, Math.min(DI_INDENT_PT.length - 1, level || 0));
