    return String((s && s.content) || "");
  }
  function _dcAllText(sections) {
    return (sections || []).map(function (s) {
      return String((s && s.name) || "") + "\n" + _dcSectionText(s);
    }).join("\n\n");
  }

  // A defined term is introduced one of three ways in practice:
  //   ("Confidential Information")      the parenthetical
  //   "Confidential Information" means  the quoted definition
  //   Confidential Information means    the bare definition
  function _dcDefinedTerms(text) {
    var out = {}, m;
    var t = String(text || "");
    // `(the "Discloser")` is as common as `("Discloser")`, so the article
    // is optional and not part of the captured term.
    var paren = new RegExp(
      "\\(\\s*(?:the|a|an)?\\s*[\"“']?((?:[A-Z][A-Za-z'’-]+\\s*){1,5})[\"”']?\\s*\\)", "g");
    while ((m = paren.exec(t)) !== null) {
      var p = m[1].trim();
      if (p && DC_NOT_TERMS.indexOf(p) === -1) out[p] = true;
    }
    var quoted = new RegExp("[\"“]([A-Z][^\"”]{1,60})[\"”]\\s+(?:means|shall mean|has the meaning)", "gi");
    while ((m = quoted.exec(t)) !== null) out[m[1].trim()] = true;
    var bare = new RegExp("\\b((?:[A-Z][A-Za-z'’-]+\\s+){0,4}[A-Z][A-Za-z'’-]+)\\s+(?:means|shall mean)\\b", "g");
    while ((m = bare.exec(t)) !== null) {
      var b = m[1].trim();
      if (b && DC_NOT_TERMS.indexOf(b) === -1) out[b] = true;
    }
    return Object.keys(out);
  }

  // Capitalised phrases used as if they were defined. Mid-sentence only —
  // a capital at the start of a sentence proves nothing.
  function _dcUsedTerms(text) {
    var out = {}, m;
    var t = String(text || "");
    var re = new RegExp("(?:[a-z,;)]\\s+)((?:[A-Z][A-Za-z'’-]+\\s+){0,3}[A-Z][A-Za-z'’-]+)", "g");
    while ((m = re.exec(t)) !== null) {
      var phrase = m[1].trim().replace(/[.,;:]+$/, "");
      if (!phrase || phrase.length < 4) continue;
      var words = phrase.split(/\s+/);
      if (words.every(function (w) { return DC_NOT_TERMS.indexOf(w) !== -1; })) continue;
      out[phrase] = (out[phrase] || 0) + 1;
    }
    return out;
  }

  function _dcNorm(s) { return String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim(); }

  // Is `used` the same term as something defined? Tolerates a plural and a
  // trailing/leading article so "the Confidential Information" matches.
  function _dcMatchesDefined(used, definedNorm) {
    var u = _dcNorm(used);
    if (!u) return true;
    if (definedNorm[u]) return true;
    if (definedNorm[u.replace(/s$/, "")]) return true;
    if (definedNorm[u + "s"]) return true;
    // A multi-word usage whose tail is a defined term ("each Receiving Party"
    // where "Receiving Party" is defined).
    var w = u.split(" ");
    for (var i = 1; i < w.length; i++) {
      if (definedNorm[w.slice(i).join(" ")]) return true;
