  function _dcCrossRefs(text) {
    var out = [], m;
    var re = new RegExp("(?:section|article|clause|§)\\s*([0-9]+(?:\\.[0-9]+)*)", "gi");
    while ((m = re.exec(String(text || ""))) !== null) out.push(m[1]);
