    // article match is case-insensitive while the label itself stays
    // capitalised — a lowercase "the supplier" is prose, not a party label.
    var re = new RegExp("\\b[Tt]he\\s+((?:Disclosing|Receiving|Purchasing|Selling|Supplying|Providing)\\s+Party|" +
