  function _dcIsPartyLabel(phrase, labels) {
    var p = _dcNorm(phrase);
    return Object.keys(labels || {}).some(function (k) { return _dcNorm(k) === p; });
  }

  function _dcIssue(kind, severity, where, what, detail) {
    return { kind: kind, severity: severity, where: where, what: what, detail: detail || "" };
  }

  // The whole check. Pure: takes the assembled sections, returns findings.
  // `docType` decides WHICH checks run: a letter has no defined terms and
  // nothing to cross-refer to, so reporting those as missing is noise —
  // and noise in a check is worse than no check, because it teaches the
  // reader to skim past the real findings.
  function _dcCheck(sections, docType) {
    var _runs = function (k) { return _dtRuns(docType, k); };
    var list = (sections || []).filter(Boolean);
    var all = _dcAllText(list);
    var issues = [];

    // 1. Sections that never got drafted.
    list.forEach(function (s) {
      if (s.status === "failed") {
        issues.push(_dcIssue("failed", "blocker", s.name,
          "This section failed to draft.", String(s.content || "")));
      } else if (!String(s.content || "").trim()) {
        issues.push(_dcIssue("empty", "blocker", s.name, "This section has no text."));
      }
    });

    // 2. Placeholders left in the draft.
    list.forEach(function (s) {
      var ph = _dcPlaceholders(_dcSectionText(s));
      if (ph.length) {
        issues.push(_dcIssue("placeholder", "warn", s.name,
          ph.length + " placeholder" + (ph.length === 1 ? "" : "s") + " still to fill.",
          ph.join(", ")));
