    var used = _dcUsedTerms(all);

    if (_runs("definedTerms")) Object.keys(used).forEach(function (u) {
      // Used repeatedly and never defined is the signal; one appearance is
      // usually a proper noun or a heading fragment.
      if (used[u] < 2) return;
      if (_dcMatchesDefined(u, definedNorm)) return;
      // Party labels are reported once, by the drift check below.
      if (_dcIsPartyLabel(u, partyLabels)) return;
      issues.push(_dcIssue("undefined_term", "warn", "",
        '"' + u + '" is used like a defined term but is never defined.',
        "appears " + used[u] + " times"));
