      Object.keys(used).forEach(function (u) {
        if (_dcMatchesDefined(u, oneNorm)) n += used[u];
      });
      if (n < 1) {
        issues.push(_dcIssue("unused_definition", "warn", "",
          '"' + d + '" is defined but never used.'));
      }
