    var nums = {};
    list.forEach(function (s) { if (s.num != null) nums[String(s.num)] = true; });
    var seenRef = {};
    if (_runs("crossRefs")) list.forEach(function (s) {
      _dcCrossRefs(_dcSectionText(s)).forEach(function (ref) {
        var top = String(ref).split(".")[0];
        if (nums[ref] || nums[top]) return;
        var key = s.name + "|" + ref;
        if (seenRef[key]) return;
        seenRef[key] = true;
        issues.push(_dcIssue("dangling_ref", "blocker", s.name,
          "Refers to Section " + ref + ", which this document does not have.",
          "sections present: " + Object.keys(nums).join(", ")));
      });
    });

    // 5. Party-label drift.
    var labels = _runs("partyDrift") ? partyLabels : {};
    var names = Object.keys(labels).filter(function (k) { return labels[k] >= 2; });
    if (names.length > 2) {
      issues.push(_dcIssue("party_drift", "warn", "",
        "The parties are referred to " + names.length + " different ways.",
        names.map(function (n) { return n + " (" + labels[n] + ")"; }).join(", ")));
    }

    // 6. Duplicate section names and numbering gaps.
    var byName = {};
    list.forEach(function (s) {
      var k = _dcNorm(s.name);
      if (!k) return;
      byName[k] = (byName[k] || 0) + 1;
    });
    Object.keys(byName).forEach(function (k) {
      if (byName[k] > 1) {
        issues.push(_dcIssue("duplicate_section", "warn", "",
          "Two sections share the name \"" + k + "\"."));
      }
    });
    var ints = list.map(function (s) { return parseInt(s.num, 10); })
      .filter(function (n) { return !isNaN(n); });
    for (var i = 1; i < ints.length; i++) {
      if (ints[i] !== ints[i - 1] && ints[i] !== ints[i - 1] + 1) {
        issues.push(_dcIssue("numbering", "warn", "",
          "Section numbering jumps from " + ints[i - 1] + " to " + ints[i] + "."));
        break;                                  // one report is enough
      }
    }

    var blockers = issues.filter(function (x) { return x.severity === "blocker"; }).length;
    return {
      issues: issues,
      blockers: blockers,
      warnings: issues.length - blockers,
      clean: issues.length === 0,
      definedTerms: defined,
