  // [SCREENS] this area's overlay screens (status → body, wiring).
  _egScreen("draft_audit",       _bodyDraftAudit,      _wireDraftAuditControls);
  _egScreen("draft_gapfill",     _bodyDraftGapfill,    _wireCancelOnly);
  _egScreen("draft_verify",      _bodyDraftVerify,     _wireDraftVerifyControls);
  _egArea("draft", { _aaStop: _aaStop });   // [AREAS] the overlay stops its auto-advance timer on close and cancel

}
